SELECT cs.canonical_smiles, md_substrate.pref_name AS substrate_compound_name, md_parent.pref_name AS parent_compound_name, met.met_conversion, met.pathway_key, met.organism, met.enzyme_name FROM metabolism met JOIN compound_records cr_substrate ON met.substrate_record_id = cr_substrate.record_id JOIN molecule_dictionary md_substrate ON cr_substrate.molregno = md_substrate.molregno JOIN compound_structures cs ON md_substrate.molregno = cs.molregno LEFT JOIN molecule_hierarchy mh ON md_substrate.molregno = mh.molregno LEFT JOIN molecule_dictionary md_parent ON mh.parent_molregno = md_parent.molregno WHERE met.enzyme_name = 'CYP2B6' LIMIT 200
